"use client";
import { SvgPathMarquee } from "@/components/block/svg-path-marquee";

const path = "M1 209.434C58.5872 255.935 387.926 325.938 482.583 209.434C600.905 63.8051 525.516 -43.2211 427.332 19.9613C329.149 83.1436 352.902 242.723 515.041 267.302C644.752 286.966 943.56 181.94 995 156.5";
const images = [
  "https://cdn-new.obsidianui.dev/effects/svg-path-marquee/svg-path-marquee-img01.png?v=3",
  "https://cdn-new.obsidianui.dev/effects/svg-path-marquee/svg-path-marquee-img02.png?v=3",
  "https://cdn-new.obsidianui.dev/effects/svg-path-marquee/svg-path-marquee-img03.png?v=3",
  "https://cdn-new.obsidianui.dev/effects/svg-path-marquee/svg-path-marquee-img04.png?v=3",
  "https://cdn-new.obsidianui.dev/effects/svg-path-marquee/svg-path-marquee-img05.png?v=3",
  "https://cdn-new.obsidianui.dev/effects/svg-path-marquee/svg-path-marquee-img06.png?v=3",
  "https://cdn-new.obsidianui.dev/effects/svg-path-marquee/svg-path-marquee-img07.png?v=3",
  "https://cdn-new.obsidianui.dev/effects/svg-path-marquee/svg-path-marquee-img08.png?v=3"
];

export default function Demo() {
  return <SvgPathMarquee path={path} viewBox="0 0 996 330" className="h-[400px] w-full overflow-hidden bg-black" responsive draggable grabCursor baseVelocity={8} repeat={2}>
